INSERT INTO company_dossiers (ticker,status,description,lede,sells,revenue_model,opportunity,must_go_right,editor_note,bull_title,bull_json,bear_title,bear_json,thesis_breaker,financial_drivers_json,risks_json,monitor_json,questions_json,competitors,evidence_date,validated_at,published_at,updated_at) VALUES
('AX','published','Digital financial-services holding company operating a nationwide bank, securities clearing and investment businesses.','Axos Financial combines branch-light consumer and commercial banking with custody, clearing and investment services. Deposit quality, net interest margin, credit cohorts, funding concentration, clearing assets, fee economics, acquisitions, capital and tangible book value per share drive value.','Consumer and business deposits, mortgages and specialty loans, treasury services, securities custody and clearing, and digital investment products.','Net interest income from loans and securities funded by deposits, plus clearing, custody, advisory and other noninterest fees.','A technology-led national model can gather deposits and serve specialized lending or securities clients without a large physical branch network.','Axos must retain stable deposits, price loans through rate cycles, control concentrated credit, operate resilient clearing systems, integrate acquired balances and compound capital without weakening underwriting.','Growth is not proof of quality. Track core and acquired deposits, uninsured and brokered mix, deposit beta, loan type and vintage, criticized assets, charge-offs, margin, clearing assets, fee concentration, capital, tangible book and diluted shares.','A branch-light platform can compound spread and fee economics at scale','["Digital distribution can support national reach with fewer physical branches.","Specialized lending and treasury relationships can earn attractive risk-adjusted spreads.","Clearing and custody can diversify revenue and deepen financial-industry relationships."]','Funding, credit concentration and operational complexity can change quickly','["Large or rate-sensitive deposits can leave or reprice rapidly.","Commercial real estate and specialty lending can produce correlated losses.","Clearing, custody and acquisition growth increase technology, compliance and integration risk."]','The thesis breaks if credit and funding losses prevent sustained growth in tangible common equity and per-share earning power through a full cycle','[{"label":"FUNDING QUALITY","value":"Liquidity proof","detail":"Core, acquired, uninsured and brokered deposits, concentration, beta and wholesale funding"},{"label":"CREDIT COHORTS","value":"Underwriting proof","detail":"Loan type, vintage, collateral, criticized assets, charge-offs and reserves"},{"label":"CAPITAL / FEES","value":"Owner outcome","detail":"Margin, clearing assets, fee mix, capital, tangible book, buybacks and diluted shares"}]','[{"title":"Deposit and liquidity","level":"High","text":"Digital and commercial balances can move quickly when rates or confidence change.","signal":"Concentration, uninsured share, outflow, beta and available liquidity"},{"title":"Credit concentration","level":"High","text":"Commercial real estate and specialty portfolios can correlate in downturns.","signal":"Vintage, collateral, criticized loans, extensions, reserves and charge-offs"},{"title":"Operations and compliance","level":"High","text":"Banking and securities platforms require resilient systems and strict controls.","signal":"Outages, examinations, enforcement, client assets and remediation"}]','[{"title":"Funding stress test","text":"Compare liquid resources with concentrated deposit outflow and rapid repricing scenarios.","impact":"BEAR CASE"},{"title":"Vintage credit ledger","text":"Track every major loan cohort from origination through criticized status, loss and recovery.","impact":"NEUTRAL"}]','["How concentrated and rate-sensitive are the largest deposit relationships?","Which loan cohorts generate returns after normalized losses and funding cost?","Do bank and securities growth compound tangible book value per diluted share?"]','SoFi, LendingClub, Customers Bancorp, Interactive Brokers, Pershing and other digital banks or clearing platforms.','2025-08-21','2026-08-06T05:13:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
